import * as react from 'react';

/** Physics feel knobs for the PullCord rope. Pass a Partial<PullCordConfig>
 *  via the `config` prop to override per instance. */
interface PullCordConfig {
    /** Hang tension / fall speed. Up = taut + fast; down = floaty. */
    gravity: number;
    /** Fraction of speed kept each frame. Up = snappier retract + more swing. */
    damping: number;
    /** Constraint solver passes per frame. Up = stiff rope; down = loose and whippy. */
    iterations: number;
    /** How far the knob can be pulled past rest. Deeper pull = bigger fly-up on release. */
    stretchMax: number;
    /** Pull depth at which onPull fires; always kept below stretchMax. */
    stretchToggle: number;
    /** Caps release speed so a hard fling cannot launch the knob. */
    maxVelocity: number;
    /** Speed below which the rope stops simulating and rests. */
    sleepVelocity: number;
}
declare const DEFAULT_CONFIG: PullCordConfig;

interface PullCordProps {
    /** Fired once per pull, the moment the pull crosses the actuation depth
     *  (like a real pull-chain detenting mid-pull), and on click / Enter. */
    onPull?: () => void;
    /** Reflected as aria-pressed on the knob (e.g. true when your light is on). */
    pulled?: boolean;
    /** Accessible name for the knob button. */
    ariaLabel?: string;
    /** Skip the drop-in entrance and start at rest. */
    noEntrance?: boolean;
    /** Partial physics overrides, merged over the defaults. */
    config?: Partial<PullCordConfig>;
    /** Extra class on the fixed wrapper (position with --pullcord-top / --pullcord-right). */
    className?: string;
}
declare function PullCord({ onPull, pulled, ariaLabel, noEntrance, config, className, }: PullCordProps): react.JSX.Element;

export { DEFAULT_CONFIG, PullCord, type PullCordConfig, type PullCordProps };
